<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('sales.create')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$db->beginTransaction();
 try{
  $saleType=$_POST['sale_type']==='wholesale'?'wholesale':'retail';$paymentType=$_POST['payment_type']==='credit'?'credit':'cash';$customerId=(int)($_POST['customer_id']??0)?:null;
  if($paymentType==='credit'){if(!$customerId)throw new RuntimeException('Choose a customer with credit enabled.');$s=$db->prepare('SELECT credit_enabled FROM customers WHERE id=?');$s->execute([$customerId]);if(!(int)$s->fetchColumn())throw new RuntimeException('Credit is not enabled for this customer. Enable it in Customers & Credit first.');if(empty($_POST['due_date']))throw new RuntimeException('Choose the credit due date.');}
  $lines=[];$subtotal=0;foreach($_POST['product_id']??[] as $i=>$pid){$qty=(float)($_POST['quantity'][$i]??0);if(!$pid||$qty<=0)continue;$s=$db->prepare('SELECT * FROM products WHERE id=? AND status="active" FOR UPDATE');$s->execute([(int)$pid]);$p=$s->fetch();if(!$p)throw new RuntimeException('A selected product is unavailable.');if($qty>(float)$p['current_stock'])throw new RuntimeException($p['name'].' only has '.$p['current_stock'].' available.');$price=(float)$p[$saleType.'_price'];$discount=max(0,(float)($_POST['line_discount'][$i]??0));$gross=$qty*$price;$lines[]=[$p,$qty,$price,$discount];$subtotal+=$gross-$discount;}
  if(!$lines)throw new RuntimeException('Add at least one product and quantity.');$invoiceDiscount=max(0,(float)($_POST['discount']??0));$total=max(0,$subtotal-$invoiceDiscount);$paid=max(0,min($total,(float)($_POST['paid_amount']??0)));if($paymentType==='cash'&&$paid<$total)throw new RuntimeException('For Pay Now, enter the full received amount. If money remains, choose Credit Sale.');$balance=$total-$paid;$status=$balance<=0?'paid':($paid>0?'partially_paid':'unpaid');$seq=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM sales')->fetchColumn();$saleNo='SALE-'.date('Y').'-'.str_pad((string)$seq,6,'0',STR_PAD_LEFT);
  $db->prepare('INSERT INTO sales(sale_no,customer_id,sale_date,sale_type,payment_type,subtotal,discount,total,paid_amount,balance,due_date,status,notes,created_by) VALUES(?,?,NOW(),?,?,?,?,?,?,?,?,?,?,?)')->execute([$saleNo,$customerId,$saleType,$paymentType,$subtotal,$invoiceDiscount,$total,$paid,$balance,$_POST['due_date']?:null,$status,trim($_POST['notes']??''),user()['id']]);$saleId=(int)$db->lastInsertId();
  $item=$db->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,historical_unit_cost,discount,line_total,gross_profit) VALUES(?,?,?,?,?,?,?,?)');$stock=$db->prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?');$move=$db->prepare('INSERT INTO stock_movements(product_id,movement_type,quantity,unit_cost,running_quantity,reference_type,reference_id,created_by) VALUES(?,?,?,?,?,?,?,?)');
  foreach($lines as [$p,$qty,$price,$discount]){$before=$qty*$price-$discount;$allocated=$subtotal>0?$invoiceDiscount*($before/$subtotal):0;$lineTotal=$before-$allocated;$profit=$lineTotal-$qty*(float)$p['avg_cost'];$item->execute([$saleId,$p['id'],$qty,$price,$p['avg_cost'],$discount+$allocated,$lineTotal,$profit]);$stock->execute([$qty,$p['id']]);$move->execute([$p['id'],$paymentType.'_sale',-$qty,$p['avg_cost'],(float)$p['current_stock']-$qty,'sale',$saleId,user()['id']]);}
  if($paid>0)$db->prepare('INSERT INTO sale_payments(sale_id,method,amount,reference_no) VALUES(?,?,?,?)')->execute([$saleId,$_POST['payment_method'],$paid,trim($_POST['reference_no']??'')]);if($customerId)$db->prepare('UPDATE customers SET outstanding=outstanding+?,total_sales=total_sales+?,total_payments=total_payments+?,last_purchase_at=NOW() WHERE id=?')->execute([$balance,$total,$paid,$customerId]);audit($db,'create','sale',$saleId,null,['sale_no'=>$saleNo,'total'=>$total,'balance'=>$balance]);$db->commit();flash('success',"Sale $saleNo saved. Stock and customer balance are updated.");redirect('sale.php?completed='.urlencode($saleNo));
 }catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('sale.php');}
}
$products=$db->query('SELECT id,item_code,name,current_stock,retail_price,wholesale_price FROM products WHERE status="active" AND current_stock>0 ORDER BY name')->fetchAll();$customers=$db->query('SELECT id,customer_code,name,customer_type,credit_enabled FROM customers WHERE status="active" ORDER BY name')->fetchAll();page_start('Make a Sale','sale.php');?>
<div class="wizard-steps"><span class="active">1 Customer</span><span>2 Products</span><span>3 Payment</span><span>4 Save</span></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><div class="sale-layout"><section><article class="panel"><div class="panel-head"><div><span class="eyebrow">Step 1</span><h3>Who is buying?</h3></div></div><div class="form-grid"><label>Customer<select name="customer_id"><option value="">Walk-in customer (no account needed)</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['customer_code'].' - '.$c['name'].($c['credit_enabled']?' (Credit OK)':''))?></option><?php endforeach;?></select></label><label>Use which price?<select name="sale_type" id="sale-type"><option value="retail">Retail price</option><option value="wholesale">Wholesale price</option></select></label><label>How will they pay?<select name="payment_type"><option value="cash">Pay Now - no money remaining</option><option value="credit">Pay Later / Part Payment - credit</option></select></label><label>Credit due date<input type="date" name="due_date"></label></div><div class="plain-help">Use Pay Now for cash, card or bank payments. Use Credit only when some money will remain after today.</div></article><article class="panel table-panel" style="margin-top:20px"><div class="panel-head"><div><span class="eyebrow">Step 2</span><h3>What are they buying?</h3></div><button type="button" class="btn secondary" id="add-line">+ Add Product</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>In stock</th><th>Qty</th><th>Discount</th><th class="right">Amount</th><th></th></tr></thead><tbody id="lines"></tbody></table></div></article></section><aside class="panel sale-summary"><div class="panel-head"><div><span class="eyebrow">Step 3</span><h3>Take payment</h3></div></div><div class="summary-row"><span>Products total</span><b id="subtotal">Rs. 0.00</b></div><label>Whole-sale discount<input type="number" name="discount" id="discount" value="0" min="0" step=".01"></label><div class="summary-row total"><span>Customer pays</span><strong id="total">Rs. 0.00</strong></div><label>Received today<input type="number" name="paid_amount" id="paid" value="0" min="0" step=".01"></label><div class="summary-row"><span>Money still due</span><b id="balance">Rs. 0.00</b></div><label>Received using<select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option><option value="other">Mixed / other</option></select></label><label>Bank / cheque reference<input name="reference_no"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><div class="plain-help">Saving creates the invoice and reduces stock automatically.</div><button class="btn primary wide" style="margin-top:12px">Save Sale</button></aside></div></form>
<template id="line-template"><tr><td><select name="product_id[]" class="product" required><option value="">Choose product</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-stock="<?=$p['current_stock']?>" data-retail="<?=$p['retail_price']?>" data-wholesale="<?=$p['wholesale_price']?>"><?=e($p['item_code'].' - '.$p['name'])?></option><?php endforeach;?></select></td><td class="stock">—</td><td><input class="qty" type="number" name="quantity[]" min=".001" step=".001" value="1"></td><td><input class="disc" type="number" name="line_discount[]" min="0" step=".01" value="0"></td><td class="right amount">Rs. 0.00</td><td><button type="button" class="icon-button remove">×</button></td></tr></template><script>const lines=document.querySelector('#lines'),tpl=document.querySelector('#line-template'),fmt=n=>'Rs. '+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function calc(){let sub=0;lines.querySelectorAll('tr').forEach(r=>{let o=r.querySelector('.product').selectedOptions[0],p=+(o?.dataset[document.querySelector('#sale-type').value]||0),a=Math.max(0,p*(+r.querySelector('.qty').value||0)-(+r.querySelector('.disc').value||0));r.querySelector('.stock').textContent=o?.dataset.stock||'—';r.querySelector('.amount').textContent=fmt(a);sub+=a});let total=Math.max(0,sub-(+discount.value||0));subtotal.textContent=fmt(sub);document.querySelector('#total').textContent=fmt(total);balance.textContent=fmt(Math.max(0,total-(+paid.value||0)))}function add(){lines.append(tpl.content.cloneNode(true));calc()}add();document.querySelector('#add-line').onclick=add;lines.addEventListener('input',calc);lines.addEventListener('change',calc);lines.addEventListener('click',e=>{if(e.target.classList.contains('remove')){e.target.closest('tr').remove();calc()}});discount.oninput=paid.oninput=document.querySelector('#sale-type').onchange=calc;</script><?php page_end();
